"""Run all stream-mining experiments and print NAME: VALUE result lines."""

from streams import RandomTreeGenerator
from evaluation import evaluate_prequential
from hoeffding_tree import HoeffdingTree


def run_vfdt_experiments():
    stream = RandomTreeGenerator(seed=42, num_attributes=10, num_classes=2,
                                 max_depth=5)
    tree = HoeffdingTree(grace_period=200, split_confidence=1e-7,
                         tie_threshold=0.05, max_depth=20, num_classes=2)
    results = evaluate_prequential(tree, stream, num_instances=100000,
                                   window_size=1000)
    size = tree.get_tree_size()
    return {
        "VFDT_ACCURACY": results["cumulative_accuracy"],
        "VFDT_TREE_NODES": size["total_nodes"],
    }


def main():
    all_results = {}
    all_results.update(run_vfdt_experiments())
    for name, value in all_results.items():
        print(f"{name}: {value}")


if __name__ == "__main__":
    main()

