"""Experiments for the ADWIN drift detector.

Covers abrupt, gradual, and recurring drift generation plus the metrics
reported by run.sh: detection delay, false positive rate, window sizes on
stable and drifting streams, and mean estimation error.
"""

import numpy as np

from stream.adwin import ADWIN


class ADWINExperiment:
    """Run ADWIN on synthetic streams with known change points."""

    def __init__(self, delta: float = 0.002):
        self.delta = delta

    # ------------------------------------------------------------------
    # stream generation
    # ------------------------------------------------------------------
    @staticmethod
    def abrupt_stream(n: int = 10000, drift_at: int = 5000,
                      mean_before: float = 0.0, mean_after: float = 1.0,
                      std: float = 1.0, seed: int = 1) -> np.ndarray:
        rng = np.random.default_rng(seed)
        before = rng.normal(mean_before, std, drift_at)
        after = rng.normal(mean_after, std, n - drift_at)
        return np.concatenate([before, after])

    @staticmethod
    def gradual_stream(n: int = 10000, drift_start: int = 4000,
                       drift_end: int = 6000, mean_before: float = 0.0,
                       mean_after: float = 1.0, std: float = 1.0,
                       seed: int = 1) -> np.ndarray:
        rng = np.random.default_rng(seed)
        means = np.full(n, mean_before)
        means[drift_end:] = mean_after
        span = drift_end - drift_start
        means[drift_start:drift_end] = np.linspace(mean_before, mean_after,
                                                   span)
        return means + rng.normal(0.0, std, n)

    @staticmethod
    def recurring_stream(n: int = 10000, period: int = 2000,
                         means=(0.0, 1.0), std: float = 1.0,
                         seed: int = 1) -> np.ndarray:
        rng = np.random.default_rng(seed)
        concept = (np.arange(n) // period) % len(means)
        base = np.array(means, dtype=float)[concept]
        return base + rng.normal(0.0, std, n)

    # ------------------------------------------------------------------
    # metrics
    # ------------------------------------------------------------------
    def _first_detection_after(self, data: np.ndarray, drift_at: int):
        """Return (detection_index, width_at_detection); None if undetected."""
        adwin = ADWIN(delta=self.delta)
        for i, value in enumerate(data):
            if adwin.add_element(float(value)) and i >= drift_at:
                return i, adwin.width
        return None

    def detection_delay(self, runs: int = 5, n: int = 10000,
                        drift_at: int = 5000, shift: float = 1.0) -> float:
        """Average delay from true drift point to first detection."""
        delays = []
        for seed in range(1, runs + 1):
            data = self.abrupt_stream(n=n, drift_at=drift_at,
                                      mean_after=shift, seed=seed)
            result = self._first_detection_after(data, drift_at)
            if result is None:
                delays.append(n - drift_at)
            else:
                delays.append(result[0] - drift_at)
        return float(np.mean(delays))

    def false_positive_rate(self, n: int = 10000, seed: int = 42) -> float:
        """Fraction of false drift signals on a stationary N(0,1) stream."""
        rng = np.random.default_rng(seed)
        data = rng.normal(0.0, 1.0, n)
        adwin = ADWIN(delta=self.delta)
        false_alarms = sum(
            1 for value in data if adwin.add_element(float(value)))
        return false_alarms / n

    def window_size_stable(self, n: int = 5000, seed: int = 42) -> float:
        """Average window size on a stationary stream (should grow)."""
        rng = np.random.default_rng(seed)
        data = rng.normal(0.0, 1.0, n)
        adwin = ADWIN(delta=self.delta)
        widths = []
        for value in data:
            adwin.add_element(float(value))
            widths.append(adwin.width)
        return float(np.mean(widths))

    def window_size_at_drift(self, runs: int = 5, n: int = 10000,
                             drift_at: int = 5000, shift: float = 1.0) -> float:
        """Window size immediately after the first drift detection."""
        widths = []
        for seed in range(1, runs + 1):
            data = self.abrupt_stream(n=n, drift_at=drift_at,
                                      mean_after=shift, seed=seed)
            result = self._first_detection_after(data, drift_at)
            if result is not None:
                widths.append(result[1])
        return float(np.mean(widths)) if widths else 0.0

    def mean_estimation_error(self, n: int = 10000, drift_at: int = 5000,
                              mean_after: float = 2.0, measure_at: int = 7000,
                              seed: int = 42) -> float:
        """Absolute error of the mean estimate after an abrupt drift."""
        data = self.abrupt_stream(n=n, drift_at=drift_at,
                                  mean_after=mean_after, seed=seed)
        adwin = ADWIN(delta=self.delta)
        for i, value in enumerate(data):
            adwin.add_element(float(value))
            if i == measure_at - 1:
                return abs(adwin.get_estimation() - mean_after)
        return abs(adwin.get_estimation() - mean_after)

    def run_all(self) -> dict:
        return {
            "ADWIN_DETECTION_DELAY": self.detection_delay(),
            "ADWIN_FALSE_POSITIVE_RATE": self.false_positive_rate(),
            "ADWIN_WINDOW_SIZE_STABLE": self.window_size_stable(),
            "ADWIN_WINDOW_SIZE_DRIFT": self.window_size_at_drift(),
            "ADWIN_MEAN_ESTIMATION_ERROR": self.mean_estimation_error(),
        }


if __name__ == "__main__":
    for name, value in ADWINExperiment().run_all().items():
        print(f"{name}: {value}")

